package org.rabochaya.projects;
import java.io.*;import java.util.*;
/** Bounded classic TIFF6 RGB/gray raster reader, uncompressed strips, explicit CRS. No URLs. */
public final class GeoTiffRaster implements Closeable {
 public static final long MAX_FILE=512L*1024*1024;private final RandomAccessFile file;private final long length;private final boolean little;private final Map<Integer,Entry> tags=new HashMap<>();
 public final GeoRasterTransform transform;public final int width,height;private final int samples,rows,photo,alpha,nodata;private final long[] offsets;private final LinkedHashMap<Integer,byte[]> rowCache=new LinkedHashMap<Integer,byte[]>(16,.75f,true){protected boolean removeEldestEntry(Map.Entry<Integer,byte[]> e){return size()>8;}};
 private static final class Entry {final int type,count;final long at;Entry(int t,int c,long a){type=t;count=c;at=a;}}
 public GeoTiffRaster(File source)throws IOException{RandomAccessFile opened=new RandomAccessFile(source,"r");file=opened;try{
  length=file.length();if(length<8||length>MAX_FILE)throw new IOException("GeoTIFF: предел файла512МиБ");int b0=file.readUnsignedByte(),b1=file.readUnsignedByte();if(b0!=b1||(b0!=73&&b0!=77))throw new IOException("Нужен TIFF с II/MM заголовком");little=b0==73;if(u16()!=42)throw new IOException("Поддерживается TIFF6; BigTIFF пока не поддержан");long ifd=u32();range(ifd,2);file.seek(ifd);int count=u16();if(count<1||count>256)throw new IOException("Слишком много TIFF tags");range(ifd+2,count*12L+4);
  for(int i=0;i<count;i++){file.seek(ifd+2+i*12L);int id=u16(),type=u16();long n=u32(),value=u32();int size=typeSize(type);if(n>Integer.MAX_VALUE)throw new IOException("Слишком большой TIFF tag");long bytes=n*size,at=bytes<=4?ifd+2+i*12L+8:value;range(at,bytes);if(tags.put(id,new Entry(type,(int)n,at))!=null)throw new IOException("Повтор TIFF tag");}
  file.seek(ifd+2+count*12L);if(u32()!=0||tags.containsKey(330))throw new IOException("Многостраничные/overview TIFF пока не поддержаны");
  width=scalar(256,-1);height=scalar(257,-1);if(width<1||height<1||width>20000||height>20000||(long)width*height>100000000)throw new IOException("GeoTIFF: допустимо до20000 по оси/100млн пикселей");
  if(scalar(259,1)!=1)throw new IOException("Пока нужен uncompressed GeoTIFF (Compression=1)");if(tags.containsKey(322)||tags.containsKey(324))throw new IOException("Tiled GeoTIFF пока не поддержан; нужны strips");if(scalar(274,1)!=1||scalar(284,1)!=1||scalar(266,1)!=1||scalar(317,1)!=1)throw new IOException("Неподдержанная orientation/planar/fill/predictor схема");if(tags.containsKey(34675))throw new IOException("ICC-профили пока не поддержаны");
  photo=scalar(262,-1);samples=scalar(277,1);int bands=photo==2?3:(photo==0||photo==1?1:-1);if(bands<0||(samples!=bands&&samples!=bands+1))throw new IOException("Нужен RGB/gray raster, palette/DEM пока не поддержаны");long[] bits=integers(258);if(bits.length!=samples)throw new IOException("Неверный BitsPerSample");for(long bit:bits)if(bit!=8)throw new IOException("Пока нужны 8-bit samples; это не DEM reader");if(tags.containsKey(339))for(long kind:integers(339))if(kind!=1)throw new IOException("Нужны unsigned samples");
  alpha=samples==bands?0:scalar(338,-1);if(samples!=bands&&alpha!=1&&alpha!=2)throw new IOException("Нужен объявленный alpha sample");long rowsValue=tags.containsKey(278)?integers(278)[0]:height;if(rowsValue<1)throw new IOException("Неверный RowsPerStrip");rows=(int)Math.min(height,rowsValue);offsets=integers(273);long[] sizes=integers(279);int strips=(height+rows-1)/rows;if(offsets.length!=strips||sizes.length!=strips)throw new IOException("Неверное число strips");for(int i=0;i<strips;i++){long bytes=(long)Math.min(rows,height-i*rows)*width*samples;if(sizes[i]!=bytes)throw new IOException("Strip byte count не соответствует raster");range(offsets[i],bytes);}
  nodata=readNoData();Map<Integer,Integer> keys=keys();int model=value(keys,1024,0),crs=model==1?value(keys,3072,0):model==2?value(keys,2048,0):0;if((model!=1||crs!=3857)&&(model!=2||crs!=4326))throw new IOException("Пока поддержаны только явные EPSG3857/4326");if(keys.containsKey(2054)&&keys.get(2054)!=9102||keys.containsKey(3076)&&keys.get(3076)!=9001)throw new IOException("Конфликт единиц CRS");int raster=value(keys,1025,1);if(raster!=1&&raster!=2)throw new IOException("Неизвестный raster type");if(tags.containsKey(34264))throw new IOException("Matrix/rotation GeoTIFF пока не поддержан");double[] scale=doubles(33550,3),tie=doubles(33922,6);if(scale[2]!=0||tie[2]!=0||tie[5]!=0)throw new IOException("3D геопривязка пока не поддержана");transform=GeoRasterTransform.scale(width,height,crs,raster==2,scale[0],scale[1],tie[0],tie[1],tie[3],tie[4]);
 }catch(Exception error){opened.close();if(error instanceof IOException)throw (IOException)error;throw new IOException("Не удалось прочитать GeoTIFF: "+error.getMessage(),error);}}
 private static int typeSize(int t)throws IOException{switch(t){case 1:case 2:case 6:case 7:return 1;case 3:case 8:return 2;case 4:case 9:case 11:return 4;case 5:case 10:case 12:return 8;default:throw new IOException("Неподдержанный TIFF type");}}
 private void range(long at,long size)throws IOException{if(at<0||size<0||at>length||size>length-at)throw new IOException("TIFF offset выходит за файл");}
 private int u16()throws IOException{int a=file.readUnsignedByte(),b=file.readUnsignedByte();return little?a|(b<<8):(a<<8)|b;}
 private long u32()throws IOException{long a=u16(),b=u16();return little?a|(b<<16):(a<<16)|b;}
 private long[] integers(int id)throws IOException{Entry e=tags.get(id);if(e==null||e.count<1||e.count>20000||(e.type!=3&&e.type!=4))throw new IOException("Нужен SHORT/LONG tag "+id);long[] values=new long[e.count];file.seek(e.at);for(int i=0;i<values.length;i++)values[i]=e.type==3?u16():u32();return values;}
 private int scalar(int id,int fallback)throws IOException{if(!tags.containsKey(id))return fallback;long[] values=integers(id);if(values.length!=1||values[0]>Integer.MAX_VALUE)throw new IOException("Неверный scalar tag "+id);return (int)values[0];}
 private double[] doubles(int id,int n)throws IOException{Entry e=tags.get(id);if(e==null||e.type!=12||e.count!=n)throw new IOException("Нужен DOUBLE tag "+id+" из "+n+" значений");double[] values=new double[n];file.seek(e.at);for(int i=0;i<n;i++){long a=u32(),b=u32();values[i]=Double.longBitsToDouble(little?a|(b<<32):(a<<32)|b);if(Double.isNaN(values[i])||Double.isInfinite(values[i]))throw new IOException("Нечисловая геопривязка");}return values;}
 private static int value(Map<Integer,Integer> keys,int id,int fallback){Integer value=keys.get(id);return value==null?fallback:value;}
 private Map<Integer,Integer> keys()throws IOException{Entry directory=tags.get(34735);if(directory==null||directory.type!=3)throw new IOException("GeoKeyDirectory должен быть SHORT");long[] data=integers(34735);if(data.length<4||data[0]!=1||data[1]!=1||data[2]>1||data.length<4+data[3]*4)throw new IOException("Неверный GeoKeyDirectory");Map<Integer,Integer> result=new HashMap<>();Set<Integer> seen=new HashSet<>();for(int i=4;i<4+data[3]*4;i+=4){int id=(int)data[i],location=(int)data[i+1],count=(int)data[i+2],offset=(int)data[i+3];if(!seen.add(id))throw new IOException("Повтор GeoKey");if(location==0){if(count!=1)throw new IOException("Неверный inline GeoKey");result.put(id,offset);}else{Entry reference=tags.get(location);if(reference==null||count<1||offset>reference.count-count)throw new IOException("GeoKey reference выходит за tag");if(id==1024||id==1025||id==2048||id==3072||id==2054||id==3076)throw new IOException("Для CRS нужен inline GeoKey");}}return result;}
 private int readNoData()throws IOException{Entry e=tags.get(42113);if(e==null)return -1;if(e.type!=2||e.count<1||e.count>32)throw new IOException("Неверный GDAL_NODATA");byte[] bytes=new byte[e.count];file.seek(e.at);file.readFully(bytes);String value=new String(bytes,"US-ASCII").replace("\0","").trim();try{double n=Double.parseDouble(value);if(n<0||n>255||n!=Math.floor(n))throw new NumberFormatException();return (int)n;}catch(NumberFormatException error){throw new IOException("Для 8-bit raster нужен целый NoData0..255");}}
 public synchronized int pixel(int x,int y)throws IOException{if(x<0||y<0||x>=width||y>=height)return 0;byte[] row=rowCache.get(y);if(row==null){row=new byte[width*samples];file.seek(offsets[y/rows]+(long)(y%rows)*width*samples);file.readFully(row);rowCache.put(y,row);}int at=x*samples,bands=photo==2?3:1;boolean empty=nodata>=0;for(int i=0;i<bands;i++)empty&=(row[at+i]&255)==nodata;if(empty)return 0;int red=row[at]&255,green=photo==2?row[at+1]&255:red,blue=photo==2?row[at+2]&255:red,a=alpha==0?255:row[at+samples-1]&255;if(photo==0){red=255-red;green=red;blue=red;}if(alpha==1){if(a==0)return 0;red=Math.min(255,(red*255+a/2)/a);green=Math.min(255,(green*255+a/2)/a);blue=Math.min(255,(blue*255+a/2)/a);}return a<<24|red<<16|green<<8|blue;}
 public int color(double lon,double lat)throws IOException{long cell=transform.cell(lon,lat);return cell<0?0:pixel((int)cell,(int)(cell>>>32));}
 public int modelColor(double x,double y)throws IOException{long cell=transform.cellModel(x,y);return cell<0?0:pixel((int)cell,(int)(cell>>>32));}
 public void close()throws IOException{rowCache.clear();file.close();}
}
